<div class="page-heading"><div><div class="eyebrow">GREAT PRODUCTS DESERVE GREAT DETAILS</div><h1><?= e($title) ?></h1><p>Choose an existing canonical product so retailers can compare equivalent offers.</p></div><a href="/listings">← All listings</a></div><form method="post" action="/listing/save" enctype="multipart/form-data" class="panel"><?= csrf() ?><input type="hidden" name="id" value="<?= $offer['id']??0 ?>"><label>Canonical product<select name="product_id" required><?php foreach($products as $p):?><option value="<?= $p['id'] ?>" <?= (int)($offer['product_id']??0)===(int)$p['id']?'selected':'' ?>><?= e($p['name'].' · '.$p['sku']) ?></option><?php endforeach;?></select></label><p class="small-muted">Need a new product? Ask the marketplace administrator to add it to the canonical catalog.</p><div class="form-row"><label>Pack size<input type="number" name="pack_size" min="0.001" step="0.001" required value="<?= e($offer['pack_size']??1) ?>"></label><label>Unit<select name="unit"><?php foreach(['each','kg','g','L','ml','lb','oz'] as $unit):?><option <?= ($offer['unit']??'each')===$unit?'selected':'' ?>><?= $unit ?></option><?php endforeach;?></select></label><label>Pack price<input name="price" inputmode="decimal" required value="<?= number_format(($offer['price']??0)/100,2,'.','') ?>"></label></div><div class="form-row"><label>Minimum packs<input name="min_qty" type="number" min="1" required value="<?= $offer['min_qty']??1 ?>"></label><label>Quantity increment<input name="increment_qty" type="number" min="1" required value="<?= $offer['increment_qty']??1 ?>"></label><label>Available stock (packs)<input name="stock" type="number" min="0" max="1000000" required value="<?= $offer['stock']??0 ?>"></label></div><label>Price tiers — one quantity:price per line<textarea name="tiers" rows="4" placeholder="12:18.00&#10;24:17.50"><?php foreach($tiers as $t)echo e($t['min_qty'].':'.number_format($t['price']/100,2,'.',''))."\n";?></textarea></label><label>Product image (JPEG / PNG / WebP, up to 4 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><small>Inventory is available stock, excluding reservations. Edits are blocked while checkout reservations are active.</small><button class="btn btn-primary">Save listing →</button></form>
